<section class="panel"><h2>Filter operations</h2><form class="inline-form" action="<?= site_url('reports') ?>" method="get"><label>From<input name="from" type="date" value="<?= esc($from,'attr') ?>"></label><label>To<input name="to" type="date" value="<?= esc($to,'attr') ?>"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['requested','scheduled','in_progress','completed','cancelled'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= esc($s) ?></option><?php endforeach ?></select></label><button type="submit">Update report</button></form><p class="muted">Filters apply to booking creation dates in Philippine time. Payment totals include recorded payments on those bookings.</p></section>
<div class="metrics"><article><strong><?= count($bookings) ?></strong><span>Bookings in range</span></article><article><strong>PHP <?= number_format($paymentTotal,2) ?></strong><span>Recorded payments</span></article></div>
<section class="panel"><label for="chart-series">Chart view<select id="chart-series"><option value="all">All charts</option><option>Bookings by status</option><option>Services requested</option><option>Bookings over time</option></select></label></section>
<?php foreach(['Bookings by status'=>$counts,'Services requested'=>$byService,'Bookings over time'=>$byMonth] as $heading=>$series): $largest=max([1,...array_values($series)]); ?><section class="panel chart-panel" data-series="<?= esc($heading,'attr') ?>"><h2><?= esc($heading) ?></h2><?php if(!$series): ?><p>No records match the current filters.</p><?php endif ?><div class="chart" role="list" aria-label="<?= esc($heading,'attr') ?>"><?php foreach($series as $label=>$count): ?><div class="chart-row" role="listitem" tabindex="0" title="<?= esc($label.': '.$count.' bookings','attr') ?>"><span><?= esc($label) ?></span><progress value="<?= (int)$count ?>" max="<?= $largest ?>"><?= (int)$count ?></progress><strong><?= (int)$count ?></strong></div><?php endforeach ?></div></section><?php endforeach ?>
<section class="panel"><h2>Booking records</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Service</th><th>Status</th><th>Created</th><th>Open</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?= (int)$b['id'] ?></td><td><?= esc($b['service_name']) ?></td><td><?= esc($b['status']) ?></td><td><?= esc($b['created_at']) ?></td><td><a href="<?= site_url('bookings/'.$b['id']) ?>">Details</a></td></tr><?php endforeach ?></tbody></table></div></section>
